test('all Fortress upper ramp bypass lanes have room and can be driven past the incline',()=>{for(const sx of [-1,1])for(const sz of [-1,1]){const r=FORT_RAMPS.find(r=>r.bottom===6&&Math.sign(r.from)===sx&&Math.sign(r.cross)===sz)!;assert.ok((Math.abs(r.from)-8)*ARENA_SCALE.fortress>=9.5);const s=match(),k=s.karts[0];k.x=sx*10*ARENA_SCALE.fortress;k.z=sz*12*ARENA_SCALE.fortress;k.y=6*ARENA_HEIGHT.fortress;k.angle=sz>0?0:Math.PI;for(let i=0;i<130;i++)drive(s,k,{...idle(),gas:1},1/60);assert.ok(k.z*sz>25*ARENA_SCALE.fortress);assert.equal(k.y,6*ARENA_HEIGHT.fortress);}});
test('shockwave broadcasts its visual origin and preserves its nine metre damage radius',()=>{const s=match(),k=s.karts[0],other=s.karts[1];other.x=8;other.z=0;k.item='pulse';useItem(s,k);assert.equal(other.balloons,2);const e=s.events.find(e=>e.type==='shockwave')!;assert.equal(e.x,k.x);assert.equal(e.z,k.z);const outside=match();outside.karts[1].x=9.1;outside.karts[0].item='pulse';useItem(outside,outside.karts[0]);assert.equal(outside.karts[1].balloons,3);const effects=new BattleEffects();effects.spawn(e);effects.update(.4);assert.equal(effects.bursts.length,1);assert.ok(effects.bursts[0].rings[0].scale.x>5);assert.ok(effects.bursts[0].rings[0].scale.x<=9);effects.update(1);assert.equal(effects.bursts.length,0);assert.equal(effects.children.length,0);});
test('pickup shatters at the box and respawn grows into full size before becoming available',()=>{const s=match(),k=s.karts[0],b=s.boxes[0];k.x=b.x+1;k.z=b.z;k.y=b.y;step(s,{});const e=s.events.find(e=>e.type==='pickup')!;assert.equal(e.x,b.x);assert.equal(e.y,b.y);assert.equal(e.z,b.z);const effects=new BattleEffects();effects.spawn(e);assert.equal(effects.bursts[0].shards!.count,16);effects.update(.2);assert.equal(effects.bursts[0].shell,undefined);assert.equal(effects.bursts[0].rings.length,0);assert.equal(effects.bursts[0].group.children.length,1,'pickup has shards only');assert.equal(boxGrowScale(6),0);assert.equal(boxGrowScale(.65),0);assert.ok(boxGrowScale(.6)>0&&boxGrowScale(.6)<.5);assert.ok(boxGrowScale(.2)>1);assert.equal(boxGrowScale(0),1);effects.update(1);assert.equal(effects.children.length,0);});

function podState(arena:Config['arena']='fortress'){const s=match();s.config.arena=arena;s.boxes=[];s.karts.forEach((k,i)=>{k.x=-80;k.z=-80-i*10;k.y=0;});return s;}
function pod(x:number,z:number,angle:number,y=.65){return {id:99,owner:0,kind:'bolt' as const,x,z,angle,y,life:8,age:0,bounces:0};}
test('pods rebound off outer walls, block faces and corners without tunnelling',()=>{const s=podState();for(const p of [pod(110,0,Math.PI/2),pod(17,48,Math.PI/2),pod(111,111,Math.PI/4)]){advanceRicochet(s,p,.2);assert.ok(p.bounces>0);assert.ok(Math.sin(p.angle)<0);assert.ok(p.life>0);assert.ok(Math.abs(p.x)<112&&Math.abs(p.z)<112);}assert.ok(s.events.some(e=>e.type==='ricochet'));});
test('pods follow ramps and bridge decks while lower pods pass underneath',()=>{const s=podState(),lower=pod(48,-14,0),upper=pod(48,-10,0,9.65);advanceRicochet(s,lower,.6);advanceRicochet(s,upper,.5);assert.equal(lower.y,.65);assert.ok(lower.life>0);assert.equal(upper.y,9.65);assert.ok(upper.life>0);const ramp=pod(10*ARENA_SCALE.fortress,24*ARENA_SCALE.fortress,Math.PI/2,9.65);advanceRicochet(s,ramp,.8);assert.ok(ramp.x>19*ARENA_SCALE.fortress);assert.equal(ramp.y,16.5+.65);assert.equal(ramp.bounces,0);});
test('pods reflect from the round bowl rim and its bumper cylinders',()=>{const s=podState('neon'),rim=pod(70,0,Math.PI/2,2.9),bumper=pod(0,40,0);advanceRicochet(s,rim,.2);advanceRicochet(s,bumper,.3);assert.ok(Math.sin(rim.angle)<0);assert.ok(rim.bounces>0);assert.ok(Math.cos(bumper.angle)<0);assert.ok(bumper.bounces>0);});
test('pods fall off open sky edges, expire after eight seconds, and can hit their owner after rebounding',()=>{const sky=podState('sky'),fall=pod(19,9,Math.PI/2);advanceRicochet(sky,fall,.2);assert.equal(fall.life,0);const s=podState(),p=pod(5,0,0);s.shots=[p];for(let i=0;i<490;i++)step(s,{});assert.equal(s.shots.length,0);const back=podState(),ricochet=pod(110.5,0,Math.PI/2);back.karts[0].x=106;back.karts[0].z=0;ricochet.age=.8;advanceRicochet(back,ricochet,.25);assert.equal(back.karts[0].balloons,2);assert.equal(ricochet.life,0);});
test('shuffle covers all arenas before refilling, preserves settings and never repeats immediately',()=>{let c:Config={...config,shuffleMaps:true,drivers:[4]};const seen=new Set([c.arena]);for(let i=0;i<ARENA_IDS.length-1;i++){const next=nextRoundConfig(c,()=>.37);assert.notEqual(next.arena,c.arena);assert.equal(next.duration,c.duration);assert.deepEqual(next.drivers,[4]);c=next;seen.add(c.arena);}assert.equal(seen.size,ARENA_IDS.length);for(let i=0;i<30;i++){const n=nextRoundConfig(c,()=>.81);assert.notEqual(n.arena,c.arena);c=n;}assert.equal(nextRoundConfig({...c,shuffleMaps:false}).arena,c.arena);});
test('wall impacts and both sides of a ram emit driver-specific reaction events without repeated wall spam',()=>{const s=match(),k=s.karts[0];k.x=111;k.z=0;k.angle=Math.PI/2;k.vx=20;k.speed=20;for(let i=0;i<20;i++)drive(s,k,{...idle(),gas:1},1/60);assert.equal(s.events.filter(e=>e.type==='crash').length,1);const ram=match();ram.karts[0].x=0;ram.karts[1].x=2;ram.karts[0].vx=20;collideKarts(ram);assert.deepEqual(ram.events.filter(e=>e.type==='bump').map(e=>e.player),[0,1]);});
test('all eight drivers have distinct reaction voices, with different hit and collision contours',()=>{assert.equal(DRIVER_VOICES.length,8);assert.equal(new Set(DRIVER_VOICES.map((_,i)=>JSON.stringify(reactionNotes(i,'hit')))).size,8);for(let i=0;i<8;i++)assert.notDeepEqual(reactionNotes(i,'hit'),reactionNotes(i,'crash'));const sound=new Sound(),notes:any[]=[];sound.ctx={currentTime:1} as AudioContext;sound.voiceTone=(note,volume)=>{notes.push({note,volume});};sound.react(4,'crash',.7);assert.equal(notes.length,2);sound.react(4,'bump',.7);assert.equal(notes.length,2);sound.react(4,'hit',.7);assert.equal(notes.length,4);sound.enabled=false;sound.react(0,'hit');assert.equal(notes.length,4);});

test('ledge markings leave Sky connectors and Fortress ramp mouths open',()=>{const sky=exposedLedges(SKY_TILES.map(t=>({...t,y:0})));assert.ok(!sky.some(e=>e.axis==='x'&&e.cross===11&&e.from<0&&e.to>0),'central north connector remains open');const decks=[];for(const sx of [-1,1])for(const sz of [-1,1])decks.push({x:sx*20,z:sz*20,width:24,depth:24,y:6},{x:sx*24,z:sz*24,width:10,depth:10,y:11});decks.push(...FORT_BRIDGES.map(b=>({...b})));const edges=exposedLedges(decks,FORT_RAMPS);assert.ok(!edges.some(e=>e.axis==='z'&&e.cross===19&&e.y===11&&e.from<24&&e.to>24),'upper ramp entrance stays open');assert.ok(edges.some(e=>e.axis==='z'&&e.cross===29&&e.y===11),'upper outside drop marked');assert.ok(!edges.some(e=>e.axis==='x'&&e.cross===8&&e.y===6&&e.from<20&&e.to>20),'bridge opening stays unmarked');});
test('every driver uses the toon model while retaining glossy balloons; item boxes retain glass material',()=>{for(let id=0;id<8;id++){const kart=createKart(id,true);assert.equal(kart.userData.toon,true);animateKart(kart,{speed:15,steering:.7,drift:.5,boost:0,vy:0},1/60,1);const balloon=kart.getObjectByName('balloon0')!;let physical=false;balloon.traverse(o=>{if(o instanceof T.Mesh&&o.material instanceof T.MeshPhysicalMaterial)physical=true;});assert.ok(physical);}const box=createItemVisual(),glass=box.getObjectByName('itemGlass') as T.Mesh;assert.ok(glass.material instanceof T.MeshPhysicalMaterial);assert.ok(glass.material.transparent&&glass.material.opacity<1);assert.ok(glass.material.roughness<.2);});

