 for(const kind of ['normal','drift','item']){const s=match(),a=s.karts[0],b=s.karts[1];a.x=b.x=0;a.z=0;b.z=2;a.angle=0;a.speed=25;a.vz=25;b.vz=0;a.boost=kind==='normal'?0:2;a.ram=kind==='item'?2:0;collideKarts(s);assert.equal(b.balloons,kind==='item'?2:3);assert.equal(a.balloons,3);collideKarts(s);assert.ok(b.balloons>=2);}
