 for(const protection of ['shield','inv','rear']){const s=match(),a=s.karts[0],b=s.karts[1];a.x=b.x=0;a.z=0;b.z=2;a.angle=protection==='rear'?Math.PI:0;a.speed=25;a.vz=25;a.boost=a.ram=2;if(protection==='shield')b.shield=4;if(protection==='inv')b.inv=2;collideKarts(s);assert.equal(b.balloons,3);if(protection==='shield')assert.equal(b.shield,0);}
