 assert.equal(normalizeSpeedClass(999),50);assert.equal(normalizeSpeedClass(undefined),50);
 for(const cc of [50,100,150] as const){const s=match(),k=s.karts[0];s.config.speedClass=cc;for(let n=0;n<400;n++){k.x=0;k.z=0;k.y=0;drive(s,k,{...idle(),gas:1},1/60);}assert.ok(Math.abs(k.speed-20*speedSettings(cc).scale)<.1);const speed=k.speed;for(let n=0;n<30;n++){k.x=k.z=k.y=0;drive(s,k,{...idle(),gas:-1},1/60);}assert.ok(k.speed<speed*.4);const next=nextRoundConfig(s.config);assert.equal(next.speedClass,cc);}
