test('rotating stadium preview fits every arena corner without a close-up depth range',()=>{const bounds=new T.Box3(new T.Vector3(-210,-12,-210),new T.Vector3(210,56,210));for(const angle of [.49,.64,.79]){const cam=new T.PerspectiveCamera(37,1.5,.1,900);cam.position.set(Math.sin(angle)*432,328,Math.cos(angle)*432);cam.lookAt(0,0,0);const range=previewDepthRange(cam,bounds);assert.ok(range.near>150);assert.ok(range.far/range.near<6);for(const x of [-210,210])for(const y of [-12,56])for(const z of [-210,210]){const depth=-new T.Vector3(x,y,z).applyMatrix4(cam.matrixWorldInverse).z;assert.ok(depth>range.near&&depth<range.far);}}});
