test('automatic driving controllers handle empty browser slots and reserve explicit assignments',()=>{const saved=globalThis.addEventListener,descriptor=Object.getOwnPropertyDescriptor(navigator,'getGamepads');globalThis.addEventListener=(()=>{}) as typeof addEventListener;const make=(index:number)=>({index,connected:true,buttons:Array.from({length:16},()=>({pressed:false,value:0})),axes:[0,0]});const first=make(2),second=make(4);let connected:any[]=[null,null,first,null,second];Object.defineProperty(navigator,'getGamepads',{configurable:true,value:()=>connected});try{const c=new Controls();c.active=true;first.buttons[7].value=1;first.axes[0]=.8;assert.equal(c.gamepad(0)?.index,2);assert.equal(c.gamepad(1)?.index,4);assert.equal(c.read(0).gas,1);assert.ok(c.read(0).steer<-.5);assert.equal(c.read(1).gas,0);c.pads[1]=2;assert.equal(c.gamepad(0)?.index,4);assert.equal(c.gamepad(1)?.index,2);assert.equal(c.read(1).gas,1);connected=[null,null,null,null,second];assert.equal(c.gamepad(1),undefined);assert.equal(c.gamepad(0)?.index,4);}finally{globalThis.addEventListener=saved;if(descriptor)Object.defineProperty(navigator,'getGamepads',descriptor);else Reflect.deleteProperty(navigator,'getGamepads');}});

test('menu handoff blocks held actions without blocking steering or throttle',()=>{const saved=globalThis.addEventListener,descriptor=Object.getOwnPropertyDescriptor(navigator,'getGamepads');globalThis.addEventListener=(()=>{}) as typeof addEventListener;const pad={index:1,connected:true,buttons:Array.from({length:16},()=>({pressed:false,value:0})),axes:[.7,.35]};Object.defineProperty(navigator,'getGamepads',{configurable:true,value:()=>[null,pad]});try{const c=new Controls();c.active=true;pad.buttons[0].pressed=true;pad.buttons[7].value=1;c.blockPads();let input=c.read(0);assert.equal(input.gas,1);assert.ok(input.steer<0);assert.equal(input.hop,false);pad.buttons[1].pressed=true;assert.equal(c.read(0).fire,true);pad.buttons[0].pressed=false;c.read(0);pad.buttons[0].pressed=true;assert.equal(c.read(0).hop,true);assert.equal(c.padLocks.size,0);c.active=false;assert.deepEqual(c.read(0),idle());}finally{globalThis.addEventListener=saved;if(descriptor)Object.defineProperty(navigator,'getGamepads',descriptor);else Reflect.deleteProperty(navigator,'getGamepads');}});

test('keyboard-only slots do not consume controllers and explicit reassignment stays unique',()=>{const saved=globalThis.addEventListener,descriptor=Object.getOwnPropertyDescriptor(navigator,'getGamepads');globalThis.addEventListener=(()=>{}) as typeof addEventListener;const pad={index:2,connected:true,buttons:Array.from({length:16},()=>({pressed:false,value:0})),axes:[0,0]};Object.defineProperty(navigator,'getGamepads',{configurable:true,value:()=>[null,null,pad]});try{const c=new Controls();c.assignPad(0,-2);assert.equal(c.gamepad(0),undefined);assert.equal(c.gamepad(1)?.index,2);c.assignPad(0,2);assert.equal(c.gamepad(0)?.index,2);assert.equal(c.gamepad(1),undefined);c.assignPad(1,2);assert.equal(c.pads[0],-1);assert.equal(c.gamepad(0),undefined);assert.equal(c.gamepad(1)?.index,2);}finally{globalThis.addEventListener=saved;if(descriptor)Object.defineProperty(navigator,'getGamepads',descriptor);else Reflect.deleteProperty(navigator,'getGamepads');}});

function customMusicHarness(){const media={paused:true,src:'',preload:'',onended:null as null|(()=>void),onerror:null as null|(()=>void),plays:0,pauses:0,loads:0,load(){this.loads++;},pause(){this.paused=true;this.pauses++;},play(){this.paused=false;this.plays++;return Promise.resolve();}},connections:unknown[]=[];const player=new ArenaMusic(()=>media as unknown as HTMLAudioElement),destination={} as AudioNode,context={createMediaElementSource:()=>({connect:(node:unknown)=>connections.push(node)})} as unknown as AudioContext;return {media,player,context,destination,connections};}
test('arena MP3s rotate, loop, pause and use the music volume bus; empty maps fall back',async()=>{const {media,player,context,destination,connections}=customMusicHarness();player.tracks.beach=[{title:'Waves',url:'/music/beach/waves.mp3'},{title:'Sunset',url:'/music/beach/sunset.mp3'}];assert.equal(player.update('castle',true,context,destination),null);assert.equal(player.update('beach',true,context,destination),'Waves');await Promise.resolve();assert.equal(media.src,'/music/beach/waves.mp3');assert.deepEqual(connections,[destination]);player.update('beach',false,context,destination);assert.equal(media.paused,true);player.update('beach',true,context,destination);await Promise.resolve();assert.equal(media.loads,1,'resume keeps playback position');media.onended!();assert.equal(player.update('beach',true,context,destination),'Sunset');await Promise.resolve();media.onended!();assert.equal(player.update('beach',true,context,destination),'Waves');await Promise.resolve();assert.equal(player.update('castle',true,context,destination),null);assert.equal(media.paused,true);});
test('broken MP3s skip to the next file then fall back without retrying forever',async()=>{const {media,player,context,destination}=customMusicHarness();player.tracks.beach=[{title:'Broken',url:'/music/beach/a.mp3'},{title:'Good',url:'/music/beach/b.mp3'}];player.update('beach',true,context,destination);await Promise.resolve();media.onerror!();assert.equal(player.update('beach',true,context,destination),'Good');await Promise.resolve();media.onerror!();assert.equal(player.update('beach',true,context,destination),null);assert.equal(media.paused,true);assert.equal(player.failed.size,2);});
test('blocked autoplay waits for user interaction rather than discarding a valid MP3',async()=>{const {media,player,context,destination}=customMusicHarness();player.tracks.beach=[{title:'Waves',url:'/music/beach/waves.mp3'}];media.play=()=>{media.plays++;return Promise.reject({name:'NotAllowedError'});};player.update('beach',true,context,destination);await Promise.resolve();await Promise.resolve();assert.equal(player.blocked,true);player.update('beach',true,context,destination);assert.equal(media.plays,1);assert.equal(player.failed.size,0);player.unlock();media.play=()=>{media.paused=false;media.plays++;return Promise.resolve();};player.update('beach',true,context,destination);await Promise.resolve();assert.equal(media.paused,false);});


test('music scenes distinguish title, arena and pause without changing the selected map',()=>{assert.equal(selectMusicScene(false,false,'castle'),'title');assert.equal(selectMusicScene(true,false,'castle'),'castle');assert.equal(selectMusicScene(true,true,'castle'),'pause');assert.equal(selectMusicScene(false,true,'beach'),'title');});
test('title and pause MP3s switch with gameplay and empty menu folders synthesize a fallback',async()=>{const {player,media,context,destination}=customMusicHarness();Object.assign(context,{currentTime:1,destination});const sound=new Sound();sound.ctx=context;sound.customMusic=player;const notes:number[]=[];sound.musicNote=(frequency:number)=>{notes.push(frequency);};player.tracks.title=[{title:'Menu',url:'/music/title/menu.mp3'}];player.tracks.pause=[{title:'Break',url:'/music/pause/break.mp3'}];player.tracks.castle=[{title:'Castle',url:'/music/castle/castle.mp3'}];for(const [scene,title] of [['title','Menu'],['castle','Castle'],['pause','Break'],['castle','Castle']] as const){sound.updateMusic('castle',true,false,scene);await Promise.resolve();assert.equal(sound.currentTrack,title+' · MP3');assert.equal(player.arena,scene);assert.equal(media.paused,false);}player.tracks.title=[];sound.updateMusic('castle',true,false,'title');assert.ok(sound.currentTrack.startsWith('Title · '));assert.ok(notes.length>0);assert.equal(media.paused,true);});

